	@ParameterizedTest(name = "range-77-all exact bag and bounded physical work: {0}")
	@MethodSource("range77Queries")
	void range77AllPreservesExactBagWithBoundedPhysicalWork(String backendName, Case fixture) throws Exception {
		Backend backend = backends.get(backendName);
		NativeQueryExpectedResults.Expected oracle = expectedResults(fixture);
		List<BindingSet> expected = oracle.rows();
		try (RepositoryConnection connection = backend.repository.getConnection()) {
			TupleQuery query = prepare(connection, fixture.query, fixture.dataset);
			Explanation explanation = query.explain(Explanation.Level.Telemetry);
			List<BindingSet> actual = evaluate(query);
			JsonNode telemetry = JSON.readTree(explanation.toJson());
			JsonNode metrics = telemetry.path("longMetricsActual");
			long sourceRowsScanned = sourceRowsScanned(explanation.toString());
			long sourceRowsMatched = sourceRowsMatched(explanation.toString());
			long sourceInputs = metrics.path("nativeRowTermDomainInputRowsActual").asLong();
			long filterEvaluations = metrics.path("nativeRowTermDomainEvaluationsActual").asLong();
			long candidateRows = candidateRows(explanation.toString());
			long statementRows = data().size();
			long facetRows = data().filter(null, iri("urn:rating"), null).size();
			long sourceWorkBound = 4L * (statementRows + facetRows);
			long aliasTermDomainBound = 2L * facetRows;
			long candidateRowsBound = 4L * (statementRows + facetRows);
			String route = telemetry.path("stringMetricsActual").path("nativeExecutionPath").asText("missing");

			Map<String, Object> metadata = new LinkedHashMap<>();
			metadata.put("fixture", fixture.id);
			metadata.put("backend", backendName);
			metadata.put("nativeTripleDatabases", backend.store.getLmdbStats().tripleDatabases().keySet());
			metadata.put("statementRows", statementRows);
			metadata.put("facetRows", facetRows);
			metadata.put("sourceRowsScannedActual", sourceRowsScanned);
			metadata.put("sourceRowsMatchedActual", sourceRowsMatched);
			metadata.put("sourceWorkBound", sourceWorkBound);
			metadata.put("nativeRowTermDomainInputRowsActual", sourceInputs);
			metadata.put("aliasTermDomainBound", aliasTermDomainBound);
			metadata.put("nativeRowTermDomainEvaluationsActual", filterEvaluations);
			metadata.put("candidateRowsActual", candidateRows);
			metadata.put("candidateRowsBound", candidateRowsBound);
			metadata.put("nativeExecutionPath", route);
			metadata.put("expectedRows", expected.stream().map(Object::toString).toList());
			metadata.put("actualRows", actual.stream().map(Object::toString).toList());
			Path artifacts = repositoryRoot()
					.resolve(
							"logs/workbench-native-fast-paths/positive-union-alias-regression-20261027/integrated-verification/range77-all")
					.resolve(backendName);
			writeEvidence(artifacts, fixture.id, fixture.query, metadata, explanation);

			oracle.assertMatches(actual, backendName + " / " + fixture.id);
			assertEfficientExecutedPlan(explanation, backendName + " / " + fixture.id);
			assertThat(route).as("executed native route for %s\n%s", fixture.id, explanation)
					.isNotBlank()
					.isNotEqualTo("missing");
			assertThat(sourceRowsScanned).as("executed source rows scanned for %s\n%s", fixture.id, explanation)
					.isPositive()
					.isLessThanOrEqualTo(sourceWorkBound);
			assertThat(sourceRowsMatched).as("executed source rows matched for %s\n%s", fixture.id, explanation)
					.isPositive()
					.isLessThanOrEqualTo(sourceWorkBound);
			assertThat(sourceInputs).as("executed alias term-domain rows for %s\n%s", fixture.id, explanation)
					.isPositive()
					.isLessThanOrEqualTo(aliasTermDomainBound);
			assertThat(filterEvaluations).as("executed facet filter evaluations for %s\n%s", fixture.id, explanation)
					.isPositive()
					.isLessThanOrEqualTo(aliasTermDomainBound);
			assertThat(candidateRows).as("executed native candidate rows for %s\n%s", fixture.id, explanation)
					.isLessThanOrEqualTo(candidateRowsBound);
		}
	}

