	@ParameterizedTest(name = "fixed blank all-facets independent bag: {0}")
	@MethodSource("nativeBackendNames")
	void fixedBlankAllFacetsPreservesIndependentBag(String backendName) throws Exception {
		String queryText = blankQueries(BLANK_IDS.get(0), "all", List.of()).path("facets").asText();
		List<BindingSet> expected = expectedFixedBlankAllFacetRows();
		Backend backend = backends.get(backendName);
		try (RepositoryConnection connection = backend.repository.getConnection()) {
			TupleQuery query = prepare(connection, queryText, null);
			Explanation explanation = query.explain(Explanation.Level.Telemetry);
			List<BindingSet> actual = evaluate(query);
			Map<String, Object> metadata = new LinkedHashMap<>();
			metadata.put("fixture", "fixed-blank-0-all-facets");
			metadata.put("backend", backendName);
			metadata.put("directAdjacencyEnabled", backend.adjacency);
			metadata.put("nativeTripleDatabases", backend.store.getLmdbStats().tripleDatabases().keySet());
			metadata.put("expectedRows", expected.stream().map(Object::toString).toList());
			metadata.put("actualRows", actual.stream().map(Object::toString).toList());
			Path artifacts = repositoryRoot().resolve(
					"logs/workbench-native-fast-paths/positive-union-alias-regression-20261027/fixed-blank-repro-red");
			writeEvidence(artifacts.resolve(backendName), "fixed-blank-all-facets", queryText, metadata, explanation);

			assertThat(bag(actual)).as("independent fixed blank all-facets bag: %s", backendName)
					.containsExactlyInAnyOrderEntriesOf(bag(expected));
			assertEfficientExecutedPlan(explanation, backendName + " / fixed-blank-0-all-facets");
		}
	}

	@ParameterizedTest(name = "fixed blank all-facets index work scales near-linearly: adjacency={0}")
	@ValueSource(booleans = { false, true })
	void fixedBlankAllFacetIndexWorkDoesNotGrowQuadratically(boolean adjacency) throws Exception {
		FixedBlankWorkMeasurement smaller = measureFixedBlankAllFacetsWork(adjacency, 256);
		FixedBlankWorkMeasurement larger = measureFixedBlankAllFacetsWork(adjacency, 512);
		SoftAssertions softly = new SoftAssertions();

		if (adjacency) {
			assertSelectedAdjacencyWork(softly, smaller);
			assertSelectedAdjacencyWork(softly, larger);
			softly.assertThat(larger.sourceRowsMatched())
					.as("same-unit matched/returned-row telemetry stays near-linear; this is not internal adjacency work; "
							+ "smaller=%s, larger=%s", smaller, larger)
					.isLessThanOrEqualTo(smaller.sourceRowsMatched() * 3L);
		} else {
			softly.assertThat(smaller.sourceRowsScanned())
					.as("completed LMDB source scans are observed at the smaller size; %s", smaller)
					.isPositive();
			softly.assertThat(larger.sourceRowsScanned())
					.as("completed LMDB source scans are observed at the larger size; %s", larger)
					.isPositive();
			softly.assertThat(smaller.selectedBoundShapes().keySet())
					.as("adjacency-off execution includes an actually selected LMDB source; %s", smaller)
					.anyMatch(shape -> shape.startsWith("LMDB|"));
			softly.assertThat(larger.selectedBoundShapes().keySet())
					.as("adjacency-off execution includes an actually selected LMDB source; %s", larger)
					.anyMatch(shape -> shape.startsWith("LMDB|"));
			softly.assertThat(larger.sourceRowsScanned())
					.as("doubling filtered candidates keeps completed LMDB source scans near-linear; smaller=%s, larger=%s",
							smaller, larger)
					.isLessThanOrEqualTo(smaller.sourceRowsScanned() * 3L);
		}
		softly.assertAll();
	}

	private static void assertSelectedAdjacencyWork(SoftAssertions softly,
			FixedBlankWorkMeasurement measurement) {
		softly.assertThat(measurement.selectedBoundShapes().keySet())
				.as("selected source telemetry proves in-memory adjacency actually ran; %s", measurement)
				.anyMatch(shape -> shape.startsWith("IN_MEMORY_ADJACENCY|"));
		softly.assertThat(measurement.sourceRowsMatched())
				.as("positive matched/returned-row telemetry is available; internal adjacency work is unmeasured; %s",
						measurement)
				.isPositive();
	}

	@ParameterizedTest(name = "fixed blank VALUES bound-prefix fanout: adjacency={0}")
	@ValueSource(booleans = { false, true })
	void fixedBlankAllFacetPrefixFanoutWorkDoesNotGrowQuadratically(boolean adjacency) throws Exception {
		FixedBlankPrefixWorkMeasurement smaller = measureFixedBlankPrefixFanoutWork(adjacency, 64, null);
		FixedBlankPrefixWorkMeasurement larger = measureFixedBlankPrefixFanoutWork(adjacency, 128, null);

		if (adjacency) {
			// Automatic planning may select a different execution tier as the fixture grows. Compare one
			// same-tier counter for the slope control, and describe it only as returned-row telemetry.
			FixedBlankPrefixWorkMeasurement forcedSmaller = measureFixedBlankPrefixFanoutWork(adjacency, 64,
					"nestedLoop");
			FixedBlankPrefixWorkMeasurement forcedLarger = measureFixedBlankPrefixFanoutWork(adjacency, 128,
					"nestedLoop");
			assertThat(forcedSmaller.sourceRowsMatched())
					.as("forced nested-loop smaller run has positive returned-row telemetry; %s", forcedSmaller)
					.isPositive();
			assertThat(forcedLarger.sourceRowsMatched())
					.as("forced nested-loop larger run has positive returned-row telemetry; %s", forcedLarger)
					.isPositive();
			assertThat(forcedLarger.sourceRowsMatched())
					.as("same-tier matched/returned-row telemetry stays near-linear; this does not measure internal adjacency work; "
							+ "smaller=%s, larger=%s", forcedSmaller, forcedLarger)
					.isLessThanOrEqualTo(forcedSmaller.sourceRowsMatched() * 3L);
		} else {
			assertThat(smaller.sourceRowsScanned())
					.as("adjacency-off uses completed LMDB source work; %s", smaller)
					.isPositive();
			assertThat(larger.sourceRowsScanned())
					.as("adjacency-off uses completed LMDB source work; %s", larger)
					.isPositive();
			assertThat(larger.sourceRowsScanned())
					.as("doubling decoy edges and facet values keeps completed LMDB scans near-linear; "
							+ "smaller=%s, larger=%s", smaller, larger)
					.isLessThanOrEqualTo(smaller.sourceRowsScanned() * 3L);
			assertThat(smaller.sourceRowsFiltered())
					.as("adjacency-off records completed LMDB filter work; %s", smaller)
					.isPositive();
			assertThat(larger.sourceRowsFiltered())
					.as("adjacency-off records completed LMDB filter work; %s", larger)
					.isPositive();
			assertThat(larger.sourceRowsFiltered())
					.as("doubling decoy edges and facet values keeps filtered LMDB source work near-linear; "
							+ "smaller=%s, larger=%s", smaller, larger)
					.isLessThanOrEqualTo(smaller.sourceRowsFiltered() * 3L);
		}
	}

	private FixedBlankPrefixWorkMeasurement measureFixedBlankPrefixFanoutWork(boolean adjacency, int fanout,
			String forcedStrategy) throws Exception {
		Model fixture = fixedBlankPrefixFanoutData(fanout);
		String runKind = forcedStrategy == null ? "automatic" : "forced-" + forcedStrategy;
		try (Backend generic = backend("fixed-blank-prefix-generic-" + adjacency + "-" + runKind + "-" + fanout,
				false, false, fixture);
				Backend nativeBackend = backend("fixed-blank-prefix-native-" + adjacency + "-" + runKind + "-" + fanout,
						true, adjacency, fixture)) {
			String queryText = blankQueries(BLANK_IDS.get(0), "all", List.of()).path("facets").asText();
			List<BindingSet> expected = expectedFixedBlankAllFacetRows();
			List<BindingSet> genericRows = evaluate(generic.repository, queryText, null);
			assertThat(bag(genericRows)).as("independent generic fixed-blank bag with %s decoy values", fanout)
					.containsExactlyInAnyOrderEntriesOf(bag(expected));

			try (RepositoryConnection connection = nativeBackend.repository.getConnection()) {
				TupleQuery query = prepare(connection, queryText, null);
				if (forcedStrategy != null) {
					((SailQuery) query).setForcedLmdbExecutionStrategy(forcedStrategy);
				}
				Explanation explanation = query.explain(Explanation.Level.Telemetry);
				List<BindingSet> actual = evaluate(query);
				String executedPlan = explanation.toString();
				JsonNode longMetrics = JSON.readTree(explanation.toJson()).path("longMetricsActual");
				long scanned = sourceRowsScanned(executedPlan);
				long matched = sourceRowsMatched(executedPlan);
				long filtered = sourceRowsFiltered(executedPlan);
				long candidates = candidateRows(executedPlan);
				long valueFilterEvaluations = nativeValueFilterEvaluations(executedPlan);
				long neighborValuesCopied = longMetrics.path("nativeIrNeighborValuesCopiedActual").asLong();
				long pagesVisited = longMetrics.path("nativeIrPagesVisitedActual").asLong();
				long pagesSkipped = longMetrics.path("nativeIrPagesSkippedActual").asLong();
				Matcher routeMatcher = NATIVE_EXECUTION_PATH.matcher(executedPlan);
				String route = routeMatcher.find() ? routeMatcher.group(1) : "missing";
				Map<String, Long> selectedBoundShapes = selectedSourceBoundShapes(executedPlan);

				Map<String, Object> metadata = new LinkedHashMap<>();
				metadata.put("fixture", "generated-fixed-blank-all-facets-with-unlabeled-decoy");
				metadata.put("backend", "native-indexes");
				metadata.put("directAdjacencyEnabled", adjacency);
				metadata.put("executionSelection", runKind);
				metadata.put("forcedStrategy", forcedStrategy);
				metadata.put("decoyWildcardEdges", fanout);
				metadata.put("decoyDistinctUrnPFacetValues", fanout);
				metadata.put("decoyRelevantBlankNodeFacetValue", "_:other");
				metadata.put("fixtureStatementCount", fixture.size());
				metadata.put("selectLimit", 300);
				metadata.put("expectedRows", expected.stream().map(Object::toString).toList());
				metadata.put("genericRows", genericRows.stream().map(Object::toString).toList());
				metadata.put("actualRows", actual.stream().map(Object::toString).toList());
				metadata.put("rowsScannedActual", scanned);
				metadata.put("rowsMatchedActual", matched);
				metadata.put("rowsFilteredActual", filtered);
				metadata.put("candidateRowsActual", candidates);
				metadata.put("nativeIrValueFilterEvaluationsActual", valueFilterEvaluations);
				metadata.put("nativeIrNeighborValuesCopiedActual", neighborValuesCopied);
				metadata.put("nativeIrPagesVisitedActual", pagesVisited);
				metadata.put("nativeIrPagesSkippedActual", pagesSkipped);
				metadata.put("adjacencyInternalWorkFullyMeasured", false);
				metadata.put("nativeExecutionPath", route);
				metadata.put("selectedSourceBoundShapes", selectedBoundShapes);
				metadata.put("sourceWorkMeasureKind", adjacency
						? matched > 0
								? "sourceRowsMatchedActual (returned-row telemetry only; internal adjacency work unmeasured)"
								: "unavailable on selected route; candidate rows are not source-work"
						: "completedLmdbRowsScanned");
				metadata.put("sourceWorkMeasureAvailable", adjacency ? matched > 0 : scanned > 0);
				metadata.put("sourceWorkMeasure", adjacency ? matched : scanned);
				metadata.put("facetPatternInPlan", executedPlan.lines()
						.filter(GraphExplorerNativeVariantsTest::hasBoundFixedBlankFacetPattern)
						.distinct()
						.toList());
				Path artifacts = repositoryRoot().resolve(
						"logs/workbench-native-fast-paths/fixed-blank-work-oracle-20261028/prefix-fanout");
				writeEvidence(artifacts.resolve("adjacency-" + adjacency + "-" + runKind), "decoys-" + fanout,
						queryText, metadata, explanation);

				assertThat(queryText).as("the actual fixed-blank producer query retains its bounded result contract")
						.contains("SELECT DISTINCT ?source ?predicate ?target", "LIMIT 300",
								"VALUES ?facetValue0 { <_:other> }");
				assertThat(genericRows).as("reference output remains below LIMIT 300").hasSize(expected.size());
				assertThat(bag(actual)).as("independent fixed-blank bag with %s decoy values; adjacency=%s", fanout,
						adjacency)
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				assertThat(actual).as("the producer LIMIT does not truncate the expected bag").hasSize(expected.size());
				assertThat(route).as("generated fixed-blank query executed native work\n%s", explanation)
						.isNotBlank()
						.isNotEqualTo("missing");
				if (forcedStrategy != null) {
					assertThat(executedPlan).as("requested route is actually executed: %s\n%s", forcedStrategy,
							explanation)
							.contains("strategy: " + forcedStrategy);
				}
				assertThat(
						executedPlan.lines().anyMatch(GraphExplorerNativeVariantsTest::hasBoundFixedBlankFacetPattern))
								.as("executed plan retains the fixed-blank facet pattern with bound predicate and object\n%s",
										explanation)
								.isTrue();
				if (adjacency) {
					if (forcedStrategy != null) {
						assertThat(matched)
								.as("forced route reports positive matched/returned-row telemetry; internal adjacency work is unmeasured\n%s",
										explanation)
								.isPositive();
					}
					assertThat(selectedBoundShapes.keySet())
							.as("executed telemetry records an actual selected in-memory adjacency source\n%s",
									explanation)
							.anyMatch(shape -> shape.startsWith("IN_MEMORY_ADJACENCY|"));
				} else {
					assertThat(scanned).as("completed native source scans\n%s", explanation).isPositive();
					assertThat(matched).as("completed native source matches\n%s", explanation).isPositive();
					assertThat(filtered).as("completed LMDB filter work\n%s", explanation).isPositive();
					assertThat(selectedBoundShapes.keySet())
							.as("executed telemetry records an actual selected LMDB source\n%s", explanation)
							.anyMatch(shape -> shape.startsWith("LMDB|"));
				}
				assertEfficientExecutedPlan(explanation, "fixed-blank-prefix-fanout / adjacency=" + adjacency
						+ " / decoys=" + fanout);

				if (!adjacency && fanout == 64) {
					assertDirectPoscLookup(nativeBackend, generic, fanout);
				}
				return new FixedBlankPrefixWorkMeasurement(fanout, fixture.size(), actual.size(), scanned, matched,
						filtered, candidates, valueFilterEvaluations, neighborValuesCopied, pagesVisited, pagesSkipped,
						route, forcedStrategy, selectedBoundShapes);
			}
		}
	}

	private static boolean hasBoundFixedBlankFacetPattern(String line) {
		int objectStart = line.indexOf("o=?facetValue0");
		return line.contains("Pattern(") && line.contains("p=const(") && objectStart >= 0
				&& line.substring(objectStart).contains("=const(");
	}

	private void assertDirectPoscLookup(Backend nativeBackend, Backend genericBackend, int fanout) throws Exception {
		String queryText = "SELECT ?focus WHERE { ?focus <urn:p> <urn:decoy:value:0> }";
		try (RepositoryConnection connection = nativeBackend.repository.getConnection()) {
			TupleQuery query = prepare(connection, queryText, null);
			Explanation explanation = query.explain(Explanation.Level.Telemetry);
			List<BindingSet> actual = evaluate(query);
			String executedPlan = explanation.toString();
			MapBindingSet expected = new MapBindingSet();
			expected.addBinding("focus", VF.createBNode("early-decoy"));
			Map<String, Object> metadata = Map.of("fixture", "predicate-object-bound-posc-control", "fanout", fanout,
					"directAdjacencyEnabled", false, "expectedRows", List.of(expected.toString()), "actualRows",
					actual.stream().map(Object::toString).toList(), "rowsScannedActual",
					sourceRowsScanned(executedPlan), "selectedSourceBoundShapes",
					selectedSourceBoundShapes(executedPlan));
			Path artifacts = repositoryRoot().resolve(
					"logs/workbench-native-fast-paths/fixed-blank-prefix-fanout-red-20261027/direct-posc-control");
			writeEvidence(artifacts, "predicate-object-bound", queryText, metadata, explanation);

			assertThat(actual).as("direct predicate/object lookup returns the one decoy facet value")
					.containsExactly(expected);
			assertThat(executedPlan)
					.as("the executed direct lookup has the POSC physical leading prefix\n%s", explanation)
					.contains("indexName=posc", "source: LMDB", "outcome: SELECTED", "subject: UNBOUND",
							"predicate: BOUND[",
							"object: BOUND[");
			assertThat(selectedSourceBoundShapes(executedPlan))
					.as("the selected LMDB access used the predicate/object bound prefix")
					.containsKey("LMDB|subject=UNBOUND,predicate=BOUND,object=BOUND,context=UNBOUND");
			assertEfficientExecutedPlan(explanation, "fixed-blank-direct-PO-prefix-control");
		}
		assertDirectBNodePoscLookup(nativeBackend, genericBackend, fanout);
	}

