			metadata.put("forcedStrategy", strategy);
			metadata.put("directAdjacencyEnabled", backend.adjacency);
			metadata.put("expectedRows", expectedFixedBlankAllFacetRows().stream().map(Object::toString).toList());
			metadata.put("actualRows", actual.stream().map(Object::toString).toList());
			Path artifacts = repositoryRoot().resolve(
					"logs/workbench-native-fast-paths/positive-union-alias-regression-20261027/fixed-blank-route-controls");
			writeEvidence(artifacts.resolve(backendName + "-" + strategy), "fixed-blank-all-facets", queryText,
					metadata, explanation);

			assertThat(explanation.toString()).as("forced route was actually executed: %s", strategy)
					.contains("strategy: " + strategy);
