	private static Model fixedBlankFacetData(Value facetValue) {
		Model data = new LinkedHashModel();
		BNode focus = VF.createBNode("alice");
		var label = VF.createLiteral("Blank resource", "en");
		for (Resource context : new Resource[] { null, iri("urn:named"), VF.createBNode("graph") }) {
			data.add(focus, iri("urn:p"), facetValue, context);
			data.add(focus, RDFS.LABEL, label, context);
			data.add(focus, RDF.TYPE, iri("urn:Type"), context);
			data.add(iri("urn:incoming"), iri("urn:p"), focus, context);
			data.add(iri("urn:classic"), RDF.SUBJECT, focus, context);
		}
		return data;
	}

	private static List<BindingSet> expectedFixedBlankFacetControlRows(Value facetValue, String bindingName) {
		List<BindingSet> expected = new ArrayList<>();
		BNode focus = VF.createBNode("alice");
		if (bindingName.isEmpty() || bindingName.equals("source")) {
			expected.add(edgeRow(focus, iri("urn:p"), facetValue));
			expected.add(edgeRow(focus, RDFS.LABEL, VF.createLiteral("Blank resource", "en")));
			expected.add(edgeRow(focus, RDF.TYPE, iri("urn:Type")));
		}
		if (bindingName.isEmpty() || bindingName.equals("target")) {
			expected.add(edgeRow(iri("urn:incoming"), iri("urn:p"), focus));
			expected.add(edgeRow(iri("urn:classic"), RDF.SUBJECT, focus));
		}
		return expected;
	}

