	private static String fixedBlankAliasIsolationQuery(String shape) {
		boolean alias = shape.startsWith("alias-");
		String focus = alias ? "?focus" : "?source";
		String focusBinding = alias ? "BIND(?source AS ?focus)\n  " : "";
		String facets = switch (shape) {
		case "alias-values", "plain-values" -> focus
				+ " <urn:p> ?facetValue0 .\n  VALUES ?facetValue0 { <_:other> }\n  "
				+ focus
				+ " <http://www.w3.org/2000/01/rdf-schema#label> ?facetValue1 .\n  VALUES ?facetValue1 { \"Blank resource\"@en }";
		case "alias-filters" -> focus + " <urn:p> ?facetValue0 .\n  FILTER(sameTerm(?facetValue0, <_:other>))\n  "
				+ focus
				+ " <http://www.w3.org/2000/01/rdf-schema#label> ?facetValue1 .\n  FILTER(sameTerm(?facetValue1, \"Blank resource\"@en))";
		case "alias-constants" -> focus + " <urn:p> <_:other> .\n  " + focus
				+ " <http://www.w3.org/2000/01/rdf-schema#label> \"Blank resource\"@en .";
		default -> throw new IllegalArgumentException(shape);
		};
		return "SELECT DISTINCT ?source ?predicate ?target WHERE {\n  ?source ?predicate ?target .\n  " + focusBinding
				+ facets + "\n}";
	}

