	private static String fixedBlankGraphUnionIsolationQuery(String graphScopes) {
		List<String> scopes = List.of(graphScopes.split("-"));
		boolean all = scopes.contains("all");
		String statement = all || scopes.contains("statement")
				? "{ ?source ?predicate ?target . } UNION { GRAPH ?__statement { ?source ?predicate ?target . } }"
				: "?source ?predicate ?target .";
		String focus = "BIND(?source AS ?focus)";
		String pFacet = all || scopes.contains("p")
				? "{ ?focus <urn:p> ?facetValue0 . } UNION { GRAPH ?__facet0 { ?focus <urn:p> ?facetValue0 . } }"
				: "?focus <urn:p> ?facetValue0 .";
		String labelFacet = all || scopes.contains("label")
				? "{ ?focus <http://www.w3.org/2000/01/rdf-schema#label> ?facetValue1 . } UNION { GRAPH ?__facet1 { ?focus <http://www.w3.org/2000/01/rdf-schema#label> ?facetValue1 . } }"
				: "?focus <http://www.w3.org/2000/01/rdf-schema#label> ?facetValue1 .";
		return "SELECT DISTINCT ?source ?predicate ?target WHERE {\n  " + statement + "\n  " + focus + "\n  "
				+ pFacet + "\n  VALUES ?facetValue0 { <_:other> }\n  " + labelFacet
				+ "\n  VALUES ?facetValue1 { \"Blank resource\"@en }\n}";
	}

