	private void assertUniformValuesOrderedControl(SoftAssertions softly, Backend generic, Backend nativeBackend,
			String suffix) throws Exception {
		String query = "SELECT ?focus ?choice WHERE { ?focus <urn:prefix:p> ?facetValue . "
				+ "VALUES (?facetValue ?choice) { (<_:generic-hosted-match> \"b\") "
				+ "(<_:generic-hosted-match> \"a\") } } ORDER BY ?focus ?choice";
		List<BindingSet> expected = List.of(
				solutionRow("focus", iri("urn:prefix:focus-a"), "choice", VF.createLiteral("a")),
				solutionRow("focus", iri("urn:prefix:focus-a"), "choice", VF.createLiteral("b")),
				solutionRow("focus", iri("urn:prefix:focus-b"), "choice", VF.createLiteral("a")),
				solutionRow("focus", iri("urn:prefix:focus-b"), "choice", VF.createLiteral("b")));
		List<BindingSet> reference = evaluate(generic.repository, query, null);
		try (RepositoryConnection connection = nativeBackend.repository.getConnection()) {
			TupleQuery nativeQuery = prepare(connection, query, null);
			Explanation explanation = nativeQuery.explain(Explanation.Level.Telemetry);
			List<BindingSet> actual = evaluate(nativeQuery);
			writeEvidence(repositoryRoot().resolve(
					"logs/workbench-native-fast-paths/fixed-blank-prefix-fanout-red-20261027/generic-hosted-prefix-red"),
					"ordered-uniform-values" + suffix, query,
					Map.of("expectedRows", expected.stream().map(Object::toString).toList(), "genericRows",
							reference.stream().map(Object::toString).toList(), "actualRows",
							actual.stream().map(Object::toString).toList()),
					explanation);
			softly.assertThat(reference).as("generic ordered bag and order").containsExactlyElementsOf(expected);
			softly.assertThat(actual).as("native ordered bag and order").containsExactlyElementsOf(expected);
		}
	}

