	private static List<BindingSet> withoutBinding(List<BindingSet> rows, String omittedName) {
		List<BindingSet> projected = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			MapBindingSet values = new MapBindingSet();
			for (String name : row.getBindingNames()) {
				if (!omittedName.equals(name)) {
					values.addBinding(name, row.getValue(name));
				}
			}
			projected.add(values);
		}
		return projected;
	}

	private static BindingSet solutionRow(Object... nameAndValues) {
		if (nameAndValues.length % 2 != 0) {
			throw new IllegalArgumentException("Binding names and values must be supplied in pairs");
		}
		MapBindingSet row = new MapBindingSet(nameAndValues.length / 2);
		for (int i = 0; i < nameAndValues.length; i += 2) {
			row.addBinding((String) nameAndValues[i], (Value) nameAndValues[i + 1]);
		}
		return row;
	}

	private static List<BindingSet> repeatedRows(BindingSet row, int count) {
		return IntStream.range(0, count).mapToObj(ignored -> row).toList();
	}

	@SafeVarargs
	private static List<BindingSet> combinedRows(List<BindingSet>... groups) {
		List<BindingSet> result = new ArrayList<>();
		for (List<BindingSet> group : groups) {
			result.addAll(group);
		}
		return result;
	}

