	private static Map<String, Long> selectedSourceBoundShapes(String telemetry) {
		String[] lines = telemetry.split("\\R");
		Map<String, Long> shapes = new LinkedHashMap<>();
		for (int i = 0; i < lines.length; i++) {
			String sourceLine = lines[i].strip();
			if (!sourceLine.startsWith("source: ")) {
				continue;
			}
			String source = sourceLine.substring("source: ".length());
			boolean selected = false;
			String subject = "unknown";
			String predicate = "unknown";
			String object = "unknown";
			String context = "unknown";
			long opens = 1L;
			for (int j = i + 1; j < lines.length; j++) {
				String line = lines[j].strip();
				if (line.startsWith("source: ") || line.equals("measurements:")) {
					break;
				}
				if (line.startsWith("outcome: ")) {
					selected = line.equals("outcome: SELECTED");
				} else if (line.startsWith("subject: ")) {
					subject = line.substring("subject: ".length()).split("\\[", 2)[0];
				} else if (line.startsWith("predicate: ")) {
					predicate = line.substring("predicate: ".length()).split("\\[", 2)[0];
				} else if (line.startsWith("object: ")) {
					object = line.substring("object: ".length()).split("\\[", 2)[0];
				} else if (line.startsWith("context: ")) {
					context = line.substring("context: ".length()).split("\\[", 2)[0];
				} else if (line.startsWith("opens: ")) {
					opens = Long.parseLong(line.substring("opens: ".length()).replace(",", ""));
				}
			}
			if (selected) {
				String shape = source + "|subject=" + subject + ",predicate=" + predicate + ",object=" + object
						+ ",context=" + context;
				shapes.merge(shape, opens, Long::sum);
			}
		}
		return shapes;
	}

	private static String skewedAliasRangeQuery(String shape) {
		String sourceArm = "?source ?predicate ?target . FILTER(?predicate != <urn:skew:rating>) "
				+ "BIND(?source AS ?focus) "
				+ "?focus <urn:skew:rating> ?facetValue . FILTER(?facetValue >= 2 && ?facetValue <= 3)";
		String targetArm = "?source ?predicate ?target . FILTER(?predicate != <urn:skew:rating>) "
				+ "BIND(?target AS ?focus) "
				+ "?focus <urn:skew:rating> ?facetValue . FILTER(?facetValue >= 2 && ?facetValue <= 3)";
		String pattern = shape.equals("union") ? "{ " + sourceArm + " } UNION { " + targetArm + " }" : sourceArm;
		return "SELECT DISTINCT ?source ?predicate ?target WHERE { " + pattern + " }\nLIMIT 300";
	}

	private static String withoutLimit(String query) {
		return query.replaceFirst("(?s)\\s+LIMIT 300\\s*$", "");
	}

	private static Model skewedAliasRangeData(int hubFanout) {
		Model data = new LinkedHashModel();
		IRI hub = iri("urn:skew:hub");
		IRI edge = iri("urn:skew:edge");
		IRI forward = iri("urn:skew:forward");
		IRI incoming = iri("urn:skew:incoming");
		for (int i = 0; i < hubFanout; i++) {
			Resource context = iri("urn:skew:hub-context:" + i);
			data.add(hub, edge, forward, context);
			data.add(incoming, edge, hub, context);
			data.add(hub, iri("urn:skew:rating"), VF.createLiteral(Integer.toString(i), XSD.INTEGER), context);
		}
		for (int i = 0; i < hubFanout * 4; i++) {
			IRI source = iri("urn:skew:other-source:" + i);
			IRI target = iri("urn:skew:other-target:" + i);
			Resource context = iri("urn:skew:other-context:" + i);
			data.add(source, edge, target, context);
			data.add(source, iri("urn:skew:rating"), VF.createLiteral(Integer.toString(10_000 + i), XSD.INTEGER),
					context);
			data.add(target, iri("urn:skew:rating"), VF.createLiteral(Integer.toString(20_000 + i), XSD.INTEGER),
					context);
		}
		return data;
	}

	private static BindingSet edgeRow(Value source, Value predicate, Value target) {
		MapBindingSet row = new MapBindingSet(3);
		row.addBinding("source", source);
		row.addBinding("predicate", predicate);
		row.addBinding("target", target);
		return row;
	}

	private static BindingSet statementRow(Value source, Value predicate, Value target) {
		MapBindingSet row = new MapBindingSet(3);
		row.addBinding("s", source);
		row.addBinding("p", predicate);
		row.addBinding("o", target);
		return row;
	}

	Stream<Arguments> inferredQueries() throws Exception {
		List<Map<String, Object>> requests = new ArrayList<>();
		List<String> names = new ArrayList<>();
		for (String scope : SCOPES) {
			add(requests, names, "labels-" + scopeId(scope), Map.of("action", "value-labels", "scope", scope,
					"values", List.of("urn:inference:focus")));
			add(requests, names, "statements-" + scopeId(scope), Map.of("action", "statements", "scope", scope,
					"sources", List.of("urn:inference:focus")));
			add(requests, names, "facets-" + scopeId(scope), Map.of("action", "facet", "scope", scope,
					"selection", List.of(List.of("__rdf_type__", List.of("urn:inference:Type")))));
		}
		List<String> queries = facetQueries(requests);
		return IntStream.range(0, queries.size())
				.boxed()
				.flatMap(index -> inferenceBackends.keySet()
						.stream()
						.flatMap(backend -> Stream.of(false, true)
								.map(inferred -> Arguments.of(backend,
										new Case(names.get(index), queries.get(index), null), inferred))));
	}

	@ParameterizedTest(name = "{0}: inferred={2}, {1}")
	@MethodSource("inferredQueries")
	void generatedQueriesRespectActualInferredOnlyRows(String backendName, Case fixture, boolean inferred)
			throws Exception {
		Backend backend = inferenceBackends.get(backendName);
		List<BindingSet> expected;
		try (RepositoryConnection connection = inferenceReference.repository.getConnection()) {
			TupleQuery query = prepare(connection, fixture.query, fixture.dataset);
			query.setIncludeInferred(inferred);
			expected = evaluate(query);
			query.setIncludeInferred(!inferred);
			assertThat(bag(expected)).as("the fixture must actually cross an inferred-only result boundary")
					.isNotEqualTo(bag(evaluate(query)));
		}
		try (RepositoryConnection connection = backend.repository.getConnection()) {
			TupleQuery query = prepare(connection, fixture.query, fixture.dataset);
			query.setIncludeInferred(inferred);
			for (String request : List.of("cold", "repeated")) {
				Explanation explanation = query.explain(Explanation.Level.Telemetry);
				List<BindingSet> actual = evaluate(query);
				Map<String, Object> metadata = Map.of("includeInferred", inferred, "backend", backendName,
						"resultCacheRequested", ((SailQuery) query).isLmdbResultCacheRequested(),
						"nativeTripleDatabases", backend.store.getLmdbStats().tripleDatabases().keySet(),
						"directAdjacencyReadiness", backend.store.getDirectAdjacencyReadinessDescription(),
						"referenceRows", expected.stream().map(Object::toString).toList(),
						"actualRows", actual.stream().map(Object::toString).toList());
				String id = fixture.id + "-inferred-" + inferred + "-" + request;
				writeEvidence(evidence.resolve("inference").resolve(backendName), id, fixture.query, metadata,
						explanation);
				assertThat(bag(actual)).as("inferred result bag: %s / %s", backendName, id)
						.containsExactlyInAnyOrderEntriesOf(bag(expected));
				assertEfficientExecutedPlan(explanation, backendName + " / " + id);
			}
		}
	}

	Stream<Arguments> fixedBlankQueries() throws Exception {
		if (fixedCases != null) {
			return arguments(fixedCases);
		}
		List<Case> cases = new ArrayList<>();
		for (int rawIndex = 0; rawIndex < BLANK_IDS.size(); rawIndex++) {
			for (String scope : SCOPES) {
				JsonNode queries = blankQueries(BLANK_IDS.get(rawIndex), scope, List.of());
				for (Map.Entry<String, JsonNode> entry : queries.properties()) {
					if (entry.getValue().isTextual()) {
						cases.add(new Case("fixed-blank-" + rawIndex + "-" + scopeId(scope) + "-" + entry.getKey(),
								entry.getValue().asText(), null));
					}
				}
			}
		}
		for (String scope : SCOPES) {
			for (String raw : List.of("only-incoming", "only-outgoing", "self-loop", "unknown")) {
				cases.add(new Case("seed-" + raw + "-" + scopeId(scope),
						blankQueries(raw, scope, List.of()).path("seed").asText(), null));
			}
			String first = blankQueries("page", scope, List.of()).path("expand").asText();
			List<BindingSet> loaded = new ArrayList<>(
					expectedResults(new Case("expand-page-first-" + scopeId(scope), first, null)).rows());
			cases.add(new Case("expand-page-first-" + scopeId(scope), first, null));
			String second = blankQueries("page", scope, loadedEdges(loaded)).path("expand").asText();
			cases.add(new Case("expand-page-next-" + scopeId(scope), second, null));
			loaded.addAll(expectedResults(new Case("expand-page-next-" + scopeId(scope), second, null)).rows());
			cases.add(new Case("expand-page-exhausted-" + scopeId(scope),
					blankQueries("page", scope, loadedEdges(loaded)).path("expand").asText(), null));
			List<Map<String, String>> documentEdges = List.of(Map.of("source", "urn:anchor", "predicate", "urn:p",
					"target", "__rdf_scoped_bnode__:" + JSON.writeValueAsString(List.of("document-1", "out-1"))));
			cases.add(new Case("expand-document-blanks-" + scopeId(scope),
					blankQueries("iri:urn:anchor", scope, documentEdges).path("expand").asText(), null));
		}
		fixedCases = List.copyOf(cases);
		return arguments(fixedCases);
	}

