	private NativeQueryExpectedResults.Expected expectedResults(Case fixture) throws Exception {
		String dataset = fixture.dataset == null ? "repository-default;includeInferred=true"
				: JSON.writeValueAsString(new TreeMap<>(Map.of(
						"defaultGraphs",
						fixture.dataset.getDefaultGraphs()
								.stream()
								.map(NativeQueryExpectedResults::canonicalTerm)
								.sorted()
								.toList(),
						"namedGraphs",
						fixture.dataset.getNamedGraphs()
								.stream()
								.map(NativeQueryExpectedResults::canonicalTerm)
								.sorted()
								.toList(),
						"defaultRemoveGraphs",
						fixture.dataset.getDefaultRemoveGraphs()
								.stream()
								.map(NativeQueryExpectedResults::canonicalTerm)
								.sorted()
								.toList(),
						"defaultInsertGraph",
						fixture.dataset.getDefaultInsertGraph() == null ? "none"
								: NativeQueryExpectedResults.canonicalTerm(fixture.dataset.getDefaultInsertGraph()),
						"includeInferred", true)));
		NativeQueryExpectedResults.Identity identity = new NativeQueryExpectedResults.Identity(fixture.query, dataset,
				fixtureFingerprint);
		NativeQueryExpectedResults.Identity previous = fixtureIdentities.putIfAbsent(fixture.id, identity);
		assertThat(previous == null || previous.equals(identity))
				.as("fixture IDs must identify one query and dataset: %s", fixture.id)
				.isTrue();
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, fixture.query, null).getTupleExpr();
		assertThat(repeatable(parsed)).as("persisted oracle must be deterministic: %s", fixture.id).isTrue();
		String key = fixture.id + "\n" + fixture.query + "\n" + dataset;
		NativeQueryExpectedResults.Expected cached = expectedResults.get(key);
		if (cached != null) {
			assertFixtureMode(cached, parsed);
			return cached;
		}
		Path file = EXPECTED_RESULTS.resolve(fixture.id + ".json");
		if (regeneratingFixtures) {
			boolean current = false;
			if (Files.exists(file) && !Boolean.getBoolean("rdf4j.workbench.nativeFixtures.force")) {
				try {
					assertFixtureMode(NativeQueryExpectedResults.read(file, identity), parsed);
					current = true;
				} catch (IOException | IllegalArgumentException stale) {
					// Only the explicit regeneration command may replace stale fixture files.
				}
			}
			if (!current) {
				long start = System.nanoTime();
				System.out.println("Generating generic oracle: " + fixture.id);
				try (var connection = reference.repository.getConnection()) {
					SailTupleQuery query = (SailTupleQuery) prepare(connection, fixture.query, fixture.dataset);
					TupleExpr expression = query.getParsedQuery().getTupleExpr();
					assertThat(repeatable(expression)).as("persisted oracle must be deterministic: %s", fixture.id)
							.isTrue();
					TupleExpr root = expression instanceof QueryRoot queryRoot ? queryRoot.getArg() : expression;
					Long limit = null;
					if (root instanceof Slice slice && slice.hasLimit() && !slice.hasOffset()
							&& !ordered(slice.getArg())) {
						limit = slice.getLimit();
						query.getParsedQuery().setTupleExpr(slice.getArg().clone());
					}
					NativeQueryExpectedResults.write(file, identity, evaluate(query), limit,
							System.getProperty("rdf4j.workbench.nativeFixtures.revision"));
				}
				System.out.printf("Generated generic oracle: %s (%.3f seconds)%n", fixture.id,
						(System.nanoTime() - start) / 1e9);
			}
		}
		NativeQueryExpectedResults.Expected result = NativeQueryExpectedResults.read(file, identity);
		assertFixtureMode(result, parsed);
		assertThat(result.generatorRevision()).as("fixture origin must be a real source revision")
				.isNotEqualTo("0".repeat(40));
		fixtureOrigins.put(fixture.id + ".json", result.generatorRevision());
		expectedResults.put(key, result);
		return result;
	}

	static Long storedUnorderedLimit(TupleExpr expression) {
		TupleExpr root = expression instanceof QueryRoot queryRoot ? queryRoot.getArg() : expression;
		return root instanceof Slice slice && slice.hasLimit() && !slice.hasOffset() && !ordered(slice.getArg())
				? slice.getLimit()
				: null;
	}

	static void assertFixtureMode(NativeQueryExpectedResults.Expected expected, TupleExpr expression) {
		assertThat(expected.unorderedLimit()).as("stored comparison mode must match the generated query")
				.isEqualTo(storedUnorderedLimit(expression));
	}

	static boolean repeatable(TupleExpr expression) {
		boolean[] repeatable = { true };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BNodeGenerator node) {
				repeatable[0] = false;
			}

			@Override
			public void meet(FunctionCall node) {
				repeatable[0] &= FunctionRegistry.getInstance()
						.get(node.getURI())
						.map(GraphExplorerNativeVariantsTest::persistentFunction)
						.orElse(false);
				super.meet(node);
			}
		});
		return repeatable[0];
	}

	private static boolean persistentFunction(Function function) {
		if (function.mustReturnDifferentResult() || function.getDeterminism() == Determinism.VOLATILE
				|| function.getURI().equals("NOW")) {
			return false;
		}
		if (function.getDeterminism() == Determinism.DETERMINISTIC) {
			return true;
		}
		// These core SPARQL implementations predate the explicit determinism contract. Unknown extension
		// implementations are not safe to freeze merely because two invocations may happen to agree.
		return Set.of("string", "xsd", "triple", "hash", "datetime", "numeric", "rdfterm")
				.stream()
				.anyMatch(group -> function.getClass()
						.getPackageName()
						.equals("org.eclipse.rdf4j.query.algebra.evaluation.function." + group));
	}

	private static boolean ordered(TupleExpr expression) {
		if (expression instanceof Order) {
			return true;
		}
		return expression instanceof UnaryTupleOperator unary && ordered(unary.getArg());
	}

	private Stream<Arguments> arguments(List<Case> cases) {
		return cases.stream()
				.flatMap(fixture -> backends.keySet().stream().map(backend -> Arguments.of(backend, fixture)));
	}

	private static void add(List<Map<String, Object>> requests, List<String> names, String id,
			Map<String, Object> request) {
		requests.add(request);
		names.add(id);
	}

	private List<String> facetQueries(List<Map<String, Object>> requests) throws Exception {
		Path input = temporary.resolve("facet-requests.json");
		Files.writeString(input, JSON.writeValueAsString(requests));
		JsonNode result = JSON
				.readTree(generate("src/test/frontend/graph-explorer/fixtures/facet-regression-bridge.mjs",
						List.of("--request-file", input.toString())));
		List<String> queries = new ArrayList<>();
		result.forEach(query -> queries.add(query.asText()));
		assertThat(queries).hasSize(requests.size());
		return queries;
	}

	private JsonNode blankQueries(String raw, String scope, List<Map<String, String>> loaded) throws Exception {
		return JSON.readTree(generate("src/test/frontend/graph-explorer/fixed-blank-node-query-fixture.mjs",
				List.of(raw, scope, JSON.writeValueAsString(Map.of("nodes", List.of(), "edges", loaded)))));
	}

	private String generate(String script, List<String> arguments) throws Exception {
		Path node = Path.of("target/node", System.getProperty("os.name").startsWith("Windows") ? "node.exe" : "node")
				.toAbsolutePath();
		Path output = Files.createTempFile(temporary, "producer-", ".json");
		Path errors = Files.createTempFile(temporary, "producer-", ".log");
		List<String> command = new ArrayList<>(List.of(node.toString(), "--experimental-strip-types", script));
		command.addAll(arguments);
		try (TestProcess child = TestProcess.start(new ProcessBuilder(command).redirectOutput(output.toFile())
				.redirectError(errors.toFile()))) {
			Process process = child.process();
			assertThat(process.waitFor(30, TimeUnit.SECONDS)).as("query producer finished: %s", script).isTrue();
			assertThat(process.exitValue()).as(Files.readString(errors)).isZero();
			return Files.readString(output);
		}
	}

	private static void assertPersistentAuthorityWithDefaultOrderPreferences(Backend backend) throws IOException {
		Properties properties = new Properties();
		try (var input = Files.newInputStream(backend.store.getDataDir().toPath().resolve("store.properties"))) {
			properties.load(input);
		}
		assertThat(properties.getProperty("triple-indexes"))
				.as("the regression retains the ordinary default logical order preferences")
				.isEqualTo("spoc,posc");
		var databases = backend.store.getLmdbStats().tripleDatabases();
		assertThat(databases).as("native statistics are available for the persistent statement authority")
				.containsKeys("adjacency-pages", "adjacency-metadata", "adjacency-deltas");
		assertThat(databases.get("adjacency-metadata").entries()).as("persistent metadata is populated").isPositive();
		assertThat(databases.get("adjacency-pages").entries() + databases.get("adjacency-deltas").entries())
				.as("the nonempty fixture has native persistent pages or deltas")
				.isPositive();
		// These are actual MDB_stat values, not a catalog enumeration or logical statement counts.
	}

	/** Run only after route/work capture, so the extra public reads cannot train the measured query. */
	private static void assertExactFixtureMembership(Backend backend, Model expected, int expectedStatementCount) {
		assertThat(expected).as("independently derived full fixture population").hasSize(expectedStatementCount);
		List<Statement> actual = new ArrayList<>();
		try (RepositoryConnection connection = backend.repository.getConnection();
				var statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				actual.add(statements.next());
			}
		}
		// A list retains unexpected duplicates; this is public statement membership, not a native-cursor work metric.
		assertThat(actual).as("every explicit fixture statement and context remains present after measured execution")
				.containsExactlyInAnyOrderElementsOf(expected);
	}

	private Backend backend(String name, boolean nativeEvaluation, boolean adjacency, Model data) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setNativeEvaluationEnabled(nativeEvaluation)
				.setDirectAdjacencyEnabled(adjacency)
				.setDirectAdjacencyMode(adjacency ? DirectAdjacencyMode.PREFER : DirectAdjacencyMode.DISABLED)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL);
		LmdbStore store = new LmdbStore(Files.createDirectories(temporary.resolve(name)).toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				connection.add(data);
				connection.commit();
			}
			if (adjacency) {
				assertThat(store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
						.as(store.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}
			return new Backend(repository, store, adjacency);
		} catch (Exception | Error failure) {
			try {
				repository.shutDown();
			} catch (Exception | Error cleanupFailure) {
				failure.addSuppressed(cleanupFailure);
			}
			throw failure;
		}
	}

	private static Model data() {
		return data(1500);
	}

	private static Model data(int hubRatingCount) {
		Model data = new LinkedHashModel();
		for (Resource context : new Resource[] { null, iri("urn:named"), VF.createBNode("graph") }) {
			for (String raw : BLANK_IDS) {
				BNode node = VF.createBNode(raw);
				BNode other = VF.createBNode("other");
				data.add(node, iri("urn:p"), other, context);
				data.add(iri("urn:incoming"), iri("urn:p"), node, context);
				data.add(node, RDFS.LABEL, VF.createLiteral("Blank resource", "en"), context);
				data.add(node, RDF.TYPE, iri("urn:Type"), context);
				data.add(iri("urn:classic"), RDF.SUBJECT, node, context);
				data.add(iri("urn:classic"), RDF.PREDICATE, iri("urn:p"), context);
				data.add(iri("urn:classic"), RDF.OBJECT, other, context);
				data.add(iri("urn:classic"), iri("urn:annotation"), VF.createLiteral("classic"), context);
				data.add(iri("urn:reifier"), RDF.REIFIES, VF.createTripleTerm(node, iri("urn:p"), other), context);
				data.add(iri("urn:reifier"), iri("urn:annotation"), VF.createLiteral("RDF 1.2"), context);
			}
			data.add(iri("urn:incoming"), iri("urn:p"), VF.createBNode("only-incoming"), context);
			data.add(VF.createBNode("only-outgoing"), iri("urn:p"), iri("urn:object"), context);
			data.add(VF.createBNode("self-loop"), iri("urn:p"), VF.createBNode("self-loop"), context);
			for (int i = 0; i < 95; i++) {
				data.add(VF.createBNode("page"), iri("urn:p"), VF.createBNode("out " + i), context);
				data.add(iri("urn:in:" + i), iri("urn:p"), VF.createBNode("page"), context);
			}
			data.add(iri("urn:anchor"), iri("urn:p"), VF.createBNode("out-1"), context);
			data.add(iri("urn:anchor"), iri("urn:p"), VF.createBNode("out-new"), context);
			addFacets(data, context, hubRatingCount);
		}
		data.add(iri("urn:source:0"), iri("urn:rating"), iri("urn:outside"), iri("urn:other"));
		data.add(iri("urn:shared"), RDFS.LABEL, VF.createLiteral("Aardvark outside", "nb"), iri("urn:other"));
		return data;
	}

	private static void addFacets(Model data, Resource context, int hubRatingCount) {
		data.add(iri("urn:a"), iri("urn:p"), iri("urn:b"), context);
		data.add(iri("urn:d"), iri("urn:p"), iri("urn:a"), context);
		for (String subject : List.of("urn:a", "urn:b", "urn:c", "urn:e")) {
			data.add(iri(subject), iri("urn:color"), iri(subject.equals("urn:b") ? "urn:blue" : "urn:red"), context);
		}
		data.add(iri("urn:a"), iri("urn:color"), iri("urn:blue"), context);
		data.add(iri("urn:e"), iri("urn:color"), VF.createBNode("paint"), context);
		data.add(iri("urn:e"), iri("urn:color"), VF.createLiteral("long value ".repeat(100)), context);
		data.add(iri("urn:a"), RDF.TYPE, iri("urn:Person"), context);
		data.add(iri("urn:a"), RDF.TYPE, iri("urn:Agent"), context);
		data.add(iri("urn:b"), RDF.TYPE, iri("urn:Org"), context);
		data.add(iri("urn:a"), iri("http://www.wikidata.org/prop/direct/P31"), iri("urn:Person"), context);
		data.add(VF.createBNode("blank"), iri("urn:q"), VF.createLiteral("bonjour", "fr"), context);
		data.add(iri("urn:t"), iri("urn:q"), VF.createLiteral("2", XSD.INTEGER), context);
		List<Value> numeric = List.of(VF.createLiteral("2"), VF.createLiteral("2.5", XSD.DECIMAL),
				VF.createLiteral("3e0", XSD.DOUBLE), VF.createLiteral(" 2.25 "), VF.createLiteral("2", "en"),
				VF.createLiteral("2", iri("urn:custom")), VF.createLiteral("+2.0", XSD.STRING),
				VF.createLiteral("\u00a02.5\u2003"), VF.createLiteral("2oops", XSD.INTEGER),
				VF.createLiteral("1e999", XSD.DOUBLE),
				VF.createLiteral("NaN"), VF.createLiteral("INF"), VF.createLiteral("0x2"), VF.createLiteral(""));
		for (int i = 0; i < numeric.size(); i++) {
			data.add(iri("urn:number:" + i), iri("urn:rating"), numeric.get(i), context);
		}
		data.add(iri("urn:a"), iri("urn:rating"), VF.createLiteral("2"), context);
		List<Value> dates = List.of(VF.createLiteral("2024", XSD.GYEAR), VF.createLiteral("2024-01", XSD.GYEARMONTH),
				VF.createLiteral("2024-01-01", XSD.DATE), VF.createLiteral("2024-01-01T23:00:00-05:00", XSD.DATETIME),
				VF.createLiteral("2024-02-29Z", XSD.DATE), VF.createLiteral("2024-02-30", XSD.DATE),
				VF.createLiteral("2024-02-29T25:00:00", XSD.DATETIME),
				VF.createLiteral("2024-02-29T12:00:00+15:00", XSD.DATETIME));
		for (int i = 0; i < dates.size(); i++) {
			data.add(iri("urn:date:" + i), iri("urn:rating"), dates.get(i), context);
		}
		for (int i = 0; i < 241; i++) {
			data.add(iri("urn:source:" + i), iri("urn:rating"), iri("urn:shared"), context);
		}
		data.add(iri("urn:shared"), RDFS.LABEL, VF.createLiteral("Shared"), context);
		data.add(iri("urn:shared"), RDFS.LABEL, VF.createLiteral("Felles", "nb"), context);
		for (int i = 0; i < hubRatingCount; i++) {
			data.add(iri("urn:hub"), iri("urn:rating"), VF.createLiteral(i), context);
		}
		data.add(iri("urn:hub"), iri("urn:rare"), VF.createLiteral("once"), context);
		Value triple = VF.createTripleTerm(iri("urn:a"), iri("urn:p"), iri("urn:b"));
		for (String reifier : List.of("urn:claim", "urn:bare", "urn:absentReifier")) {
			data.add(iri(reifier), RDF.REIFIES, triple, context);
		}
		for (String reification : List.of("urn:classic", "urn:empty", "urn:absentClassic")) {
			data.add(iri(reification), RDF.SUBJECT, iri("urn:a"), context);
			data.add(iri(reification), RDF.PREDICATE, iri("urn:p"), context);
			data.add(iri(reification), RDF.OBJECT, iri("urn:b"), context);
		}
		for (String about : List.of("urn:claim", "urn:classic")) {
			data.add(iri(about), iri("urn:confidence"), VF.createLiteral("selected"), context);
			data.add(iri(about), iri("urn:confidence"), VF.createLiteral("outside"), iri("urn:other"));
		}
		data.add(iri("urn:bare"), iri("urn:confidence"), VF.createLiteral("outside"), iri("urn:other"));
		data.add(iri("urn:empty"), iri("urn:confidence"), VF.createLiteral("outside"), iri("urn:other"));
		data.add(iri("urn:reference"), iri("urn:believes"), triple, context);
		data.add(iri("urn:outsideReference"), iri("urn:believes"), triple, iri("urn:other"));
	}

	private static List<Map<String, String>> loadedEdges(List<BindingSet> rows) {
		return rows.stream()
				.map(row -> Map.of("source", nodeId(row.getValue("source")),
						"predicate", row.getValue("predicate").stringValue(), "target", nodeId(row.getValue("target"))))
				.toList();
	}

	private static String nodeId(Value value) {
		return value instanceof BNode blank ? BlankNodeReferences.toReference(blank.getID()) : value.stringValue();
	}

	private static IRI iri(String value) {
		return VF.createIRI(value);
	}

	private static List<BindingSet> evaluate(SailRepository repository, String query, Dataset dataset) {
		try (RepositoryConnection connection = repository.getConnection()) {
			return evaluate(prepare(connection, query, dataset));
		}
	}

	private static TupleQuery prepare(RepositoryConnection connection, String text, Dataset dataset) {
		TupleQuery query = connection.prepareTupleQuery(text);
		((SailQuery) query).setLmdbResultCacheRequested(false);
		if (dataset != null) {
			query.setDataset(dataset);
		}
		return query;
	}

	private static List<BindingSet> evaluate(TupleQuery query) {
		try (var result = query.evaluate()) {
			return new ArrayList<>(result.stream().toList());
		}
	}

	private static String scopeId(String scope) {
		return switch (scope) {
		case "urn:named" -> "named";
		case "<_:graph>" -> "blank-graph";
		default -> scope;
		};
	}

	private static Path repositoryRoot() {
		Path path = Path.of("").toAbsolutePath();
		while (path != null && !Files.isDirectory(path.resolve(".git")) && !Files.isRegularFile(path.resolve(".git"))) {
			path = path.getParent();
		}
		assertThat(path).isNotNull();
		return path;
	}

