	private static final class EffectSequenceFunction implements Function {

		private final AtomicInteger calls;

		private EffectSequenceFunction(AtomicInteger calls) {
			this.calls = calls;
		}

		@Override
		public String getURI() {
			return "urn:workbench:test:sequence";
		}

		@Override
		@SuppressWarnings("deprecation")
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			return valueFactory.createLiteral(calls.incrementAndGet());
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.VOLATILE;
		}

		@Override
		public boolean mustReturnDifferentResult() {
			return true;
		}
	}

	private record Case(String id, String query, Dataset dataset) {
		@Override
		public String toString() {
			return id;
		}
	}
